import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    k = int(input_data[0])
    n = 1 << k
    a = []
    idx = 1
    for _ in range(n):
        a.append(int(input_data[idx]))
        idx += 1

    cnt = Counter(a)

    def build_permutations(target_counts, current_p, current_q, depth):
        if depth == n:
            return True, current_p, current_q

        val = depth
        needed = target_counts[val]

        if needed == 0:
            return build_permutations(target_counts, current_p, current_q, depth + 1)

        found_p = -1
        found_q = -1

        for x in range(n):
            if x in current_p:
                continue
            y = x ^ val
            if y in current_q:
                continue

            if cnt.get(val, 0) > 0:
                pass
            else:
                continue

            current_p.add(x)
            current_q.add(y)

            success, p_res, q_res = build_permutations(target_counts, current_p, current_q, depth + 2)
            if success:
                return True, p_res, q_res

            current_p.remove(x)
            current_q.remove(y)

        return False, [], []

    if sum(cnt.values()) != n:
        print("Fou")
        return

    if cnt[0] % 2 != 0:
        print("Fou")
        return

    p = [0] * n
    q = [0] * n
    used_p = set()
    used_q = set()

    def backtrack(idx):
        if idx == n:
            return True

        target_val = a[idx]

        for x in range(n):
            if x in used_p:
                continue
            y = x ^ target_val
            if y in used_q:
                continue

            if cnt[target_val] > 0:
                used_p.add(x)
                used_q.add(y)
                p[idx] = x
                q[idx] = y

                if backtrack(idx + 1):
                    return True

                used_p.remove(x)
                used_q.remove(y)

        return False

    if backtrack(0):
        print("Shi")
        print(*(p))
        print(*(q))
    else:
        print("Fou")

solve()
